<div class="actions"><a class="button" href="<?= escapar(url('entrega-nueva')) ?>">Preparar nueva entrega</a></div><div class="notice">Las entregas registradas corresponden exclusivamente al flujo Almacén → Servicio Regional.</div><div class="table-wrap"><table><thead><tr><th>Folio</th><th>Almacén</th><th>Servicio Regional</th><th>Programada</th><th>Salida</th><th>Estado</th><th>Uniformes enviados</th><th></th></tr></thead><tbody><?php if(!$entregas): ?><tr><td colspan="8" class="empty">Sin entregas regionales.</td></tr><?php endif; foreach($entregas as $e): ?><tr><td><?= escapar($e['folio']) ?></td><td><?= escapar($e['almacen']) ?></td><td><?= escapar($e['servicio_regional']) ?></td><td><?= escapar($e['fecha_programada']??'—') ?></td><td><?= escapar($e['fecha_salida']??'—') ?></td><td><span class="status"><?= escapar(str_replace('_',' ',$e['estado'])) ?></span></td><td><?= numero($e['total']) ?></td><td><a href="<?= escapar(url('entrega-detalle',['id'=>$e['id']])) ?>">Ver detalle</a></td></tr><?php endforeach; ?></tbody></table></div>
